type TreeNode = { val: number; left: TreeNode | null; right: TreeNode | null };

function inorder(root: TreeNode | null, out: number[] = []): number[] {
  if (!root) return out;
  inorder(root.left, out);
  out.push(root.val);
  inorder(root.right, out);
  return out;
}

function levelOrder(root: TreeNode | null): number[][] {
  const levels: number[][] = [];
  let level = root ? [root] : [];
  while (level.length > 0) {
    levels.push(level.map((n) => n.val));
    level = level.flatMap((n) => [n.left, n.right].filter((c): c is TreeNode => c !== null));
  }
  return levels;
}

